mapper.select:
/** * selectMnthngSchdlList01 : isry.couns.taskwkschmng.schprecon.mapper.MnthngSchdlMapper : 월간일정 LIST 조회(일정) */ SELECT DISTINCT BB.CRTR_YM AS CRTR_YM , AA.USER_ID AS USER_ID , C##RG.DEC_B64(DD.FLNM_ENCPT) AS USER_NM , AA.WORK_YMD AS WORK_YMD , BB.MBR_NOCS AS MBR_NOCS , BB.BGNG_HR AS BGNG_HR , BB.END_HR AS END_HR , BB.TASKWK_TYPE_DEPT_CD AS DEPT_CD , AA.TASKWK_SCHDL_SN AS TASKWK_SCHDL_SN FROM AYC100 AA /** 근무배정표 일별 **/ , AYC110 BB /** 근무배정표 월별 **/ , SAA200 CC /** 사용자 **/ , SCA100 DD /** 종사자 **/ WHERE 1=1 AND AA.BIZ_PLAN_MNG_NO = BB.BIZ_PLAN_MNG_NO AND AA.USER_ID = CC.USER_ID AND CC.ENFSN_NO = DD.ENFSN_NO AND AA.DEL_YN = 'N'
AND BB.CRTR_YM = #{crtrYm}
AND BB.TASKWK_TYPE_DEPT_CD = #{deptCd}
GROUP BY AA.WORK_YMD,BB.BGNG_HR,BB.END_HR,AA.USER_ID,C##RG.DEC_B64(DD.FLNM_ENCPT),BB.CRTR_YM,BB.MBR_NOCS,BB.TASKWK_TYPE_DEPT_CD,AA.TASKWK_SCHDL_SN ORDER BY AA.WORK_YMD,BB.BGNG_HR, C##RG.DEC_B64(DD.FLNM_ENCPT)

mapper.update:
    /**
	*		updateMnthngSchdlDetail : isry.couns.taskwkschmng.schprecon.mapper.MnthngSchdlMapper : 월간 일정  상세 수정
	*/
	    UPDATE
				AYC100		AA		/**근무배정표 일별**/
		SET
				LAST_MDFR_ID		=	#{loginId}
			,	LAST_MDFCN_DT		=	SYSDATE
			,	AA.BIZ_PLAN_MNG_NO	=	#{bizPlanMngNo}
		WHERE	1=1
			AND	AA.TASKWK_SCHDL_SN	=	#{taskwkSchdlSn}
			AND	AA.USER_ID			=	#{userId}

mapper.delete:
    /**
	*		deleteMnthngSchdlDetail : isry.couns.taskwkschmng.schprecon.mapper.MnthngSchdlMapper : 월간 일정  상세 삭제
	*/
		DELETE
		FROM
				AYC100		AA		/**근무배정표 일별**/
		WHERE	1=1
			AND	AA.TASKWK_SCHDL_SN	=	#{taskwkSchdlSn}
			AND	AA.USER_ID			=	#{userId}

mapper.select:
/** * selectYmdSchdlExmpl : isry.couns.taskwkschmng.schprecon.mapper.MnthngSchdlMapper : 월간 일자별 상세 조회 */ SELECT AA.WORK_YMD AS WORK_YMD , AA.USER_ID AS USER_ID , C##RG.DEC_B64(DD.FLNM_ENCPT) AS USER_NM , BB.BGNG_HR AS BGNG_HR , BB.END_HR AS END_HR FROM AYC100 AA , AYC110 BB , SAA200 CC /** 사용자 **/ , SCA100 DD /** 종사자 **/ WHERE 1=1 AND AA.BIZ_PLAN_MNG_NO = BB.BIZ_PLAN_MNG_NO AND AA.USER_ID = CC.USER_ID AND CC.ENFSN_NO = DD.ENFSN_NO
AND AA.WORK_YMD LIKE #{workYmd}
AND BB.TASKWK_TYPE_DEPT_CD = #{deptCd}

/** * selectMnthForExclDown : isry.couns.taskwkschmng.schprecon.mapper.MnthngSchdlMapper : 월간 일자 엑셀 다운로드 시간표 조회 */ WITH ZZ AS ( SELECT BB.USER_ID AS CNSLTNT_ID , C##RG.DEC_B64(DD.FLNM_ENCPT) AS CNSLTNT_NM , AA.BGNG_HR AS BGNG_HR , BB.WORK_YMD AS WORK_YMD , COUNT(*) AS CCNT , EE.HR_WORK_TYPE_SE_CD1 AS HR_WORK_TYPE_SE_CD1 , EE.HR_WORK_TYPE_SE_CD2 AS HR_WORK_TYPE_SE_CD2 FROM AYC110 AA , AYC100 BB , SAA200 CC , SCA100 DD , AYC120 EE WHERE 1=1 AND AA.CRTR_YM = #{crtrYm} AND AA.TASKWK_TYPE_DEPT_CD = #{deptCd} AND AA.BIZ_PLAN_MNG_NO = BB.BIZ_PLAN_MNG_NO AND BB.USER_ID = CC.USER_ID AND CC.ENFSN_NO = DD.ENFSN_NO AND EE.TASKWK_SCHDL_SN (+) = BB.TASKWK_SCHDL_SN GROUP BY BB.USER_ID , DD.FLNM_ENCPT , BB.WORK_YMD , AA.BGNG_HR , EE.HR_WORK_TYPE_SE_CD1 , EE.HR_WORK_TYPE_SE_CD2 ORDER BY 1, 2 ) SELECT * FROM ZZ PIVOT ( SUM(CCNT) FOR BGNG_HR IN
'${item}' AS TIME${index}
)

mapper.insert:
    /**
	*		insertDaySchdlOut : isry.couns.taskwkschmng.schprecon.mapper.MnthngSchdlMapper : 월간일정 일괄생성 등록 아웃리치
	*/
		    INSERT INTO
					AYC120		/** 근무배정표 아웃리치 **/
					(
							INDEX_SN
						,	TASKWK_SCHDL_SN
						,	USER_ID
						,	HR_WORK_TYPE_SE_CD1
						,	HR_WORK_TYPE_SE_CD2
						,	FRST_RGTR_ID
						,	FRST_REG_DT
						,	LAST_MDFR_ID
						,	LAST_MDFCN_DT
					)

			VALUES
					(
							AYC120_SQ01.NEXTVAL
						,	#{TASKWK_SCHDL_SN}
						,	#{CNSLTNT_ID}
						,	#{firstCd}
						,	#{secondCd}
						,	#{loginId}
						,	SYSDATE
						,	#{loginId}
						,	SYSDATE
					)

    /**
	*		insertMnthngSchdlOut : isry.couns.taskwkschmng.schprecon.mapper.MnthngSchdlMapper : 월간 일정 등록(아웃리치)
	*/
				INSERT INTO
						AYC120		/** 근무배정표 아웃리치 **/
						(
								INDEX_SN
							,	TASKWK_SCHDL_SN
							,	USER_ID
							,	HR_WORK_TYPE_SE_CD1
							,	HR_WORK_TYPE_SE_CD2
							,	FRST_RGTR_ID
							,	FRST_REG_DT
							,	LAST_MDFR_ID
							,	LAST_MDFCN_DT
						)

				VALUES
						(
								AYC120_SQ01.NEXTVAL
							,	#{TASKWK_SCHDL_SN}
							,	#{CNSLTNT_ID}
							,	#{FIRST_CD}
							,	#{SECOND_CD}
							,	#{loginId}
							,	SYSDATE
							,	#{loginId}
							,	SYSDATE
						)
